VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: starts with a vowel, or with "xr" or "yt"
    if word[0] in VOWELS or word.startswith(("xr", "yt")):
        return word + "ay"

    # Find the end of the leading consonant cluster.
    # A "y" after at least one consonant acts as a vowel (Rule 4).
    i = 1
    while i < len(word) and word[i] not in VOWELS and word[i] != "y":
        i += 1

    # Rule 3: a "qu" at the end of the cluster moves along with it.
    if word[i - 1] == "q" and i < len(word) and word[i] == "u":
        i += 1

    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split())

